import{_ as e,o as s,c as a,a2 as i}from"./chunks/framework.DGu13UIe.js";const g=JSON.parse('{"title":"第 53 课 · Diff 预览与 Accept 写盘","description":"","frontmatter":{"editLink":"https://github.com/SyncLionPaw/bagent/edit/main/lessons/53-diff-preview/doc.md"},"headers":[],"relativePath":"chapters/53-diff-preview.md","filePath":"chapters/53-diff-preview.md"}'),n={name:"chapters/53-diff-preview.md"};function o(d,t,p,l,r,c){return s(),a("div",null,[...t[0]||(t[0]=[i(`<h1 id="第-53-课-·-diff-预览与-accept-写盘" tabindex="-1">第 53 课 · Diff 预览与 Accept 写盘 <a class="header-anchor" href="#第-53-课-·-diff-预览与-accept-写盘" aria-label="Permalink to &quot;第 53 课 · Diff 预览与 Accept 写盘&quot;">​</a></h1><p><strong>约 35 分钟</strong> · <a href="/bagent/chapters/52-edit-proposal.html">第 52 课</a> 之后 · <strong>独立插件</strong></p><p><a href="/bagent/chapters/52-edit-proposal.html">第 52 课</a> 已在 worker 里把 <code>write_file</code> / <code>str_replace</code> / <code>delete_file</code> 改成<strong>只出提案、不落盘</strong>。但审批仍在侧栏点 ✓/✗，中间编辑器毫无动静——还不是 Cursor 那种体验。</p><p>本课接上 VS Code <strong>编辑器本体</strong>：并排 diff 预览 → 标题栏 <strong>Accept / Reject</strong> → 只有你 Accept 才 <code>applyEdit</code> 写盘。侧栏继续负责聊天；<strong>红绿对比和写盘确认在中间的 diff 里</strong>。</p><hr><h2 id="_1-本课相对第-51–52-课多了什么" tabindex="-1">1. 本课相对第 51–52 课多了什么 <a class="header-anchor" href="#_1-本课相对第-51–52-课多了什么" aria-label="Permalink to &quot;1. 本课相对第 51–52 课多了什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>第 51 课</th><th>第 52 课</th><th>第 53 课（本课）</th></tr></thead><tbody><tr><td>worker 写盘</td><td><code>fs</code> 直接写</td><td>只算提案</td><td>只算提案（同 52）</td></tr><tr><td>用户确认</td><td>侧栏 ✓/✗</td><td>侧栏 ✓/✗</td><td><strong>diff 标题栏 Accept / Reject</strong></td></tr><tr><td>预览</td><td>无</td><td>无</td><td><strong><code>vscode.diff</code> 左旧右新</strong></td></tr><tr><td>写盘执行方</td><td>worker</td><td>无</td><td><strong>Extension Host <code>applyEdit</code></strong></td></tr></tbody></table><p><code>run_command</code> 仍走侧栏 danger 审批，与本课无关。</p><hr><h2 id="_2-整条链路" tabindex="-1">2. 整条链路 <a class="header-anchor" href="#_2-整条链路" aria-label="Permalink to &quot;2. 整条链路&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户说话</span></span>
<span class="line"><span>  → 模型调 write_file / str_replace / delete_file</span></span>
<span class="line"><span>  → worker 内存算出 oldContent / newContent（不落盘）</span></span>
<span class="line"><span>  → stdout 发出 EditProposal 事件</span></span>
<span class="line"><span>  → Extension Host：</span></span>
<span class="line"><span>       虚拟 URI（bagent-old / bagent-new）灌入全文</span></span>
<span class="line"><span>       vscode.diff 打开并排预览</span></span>
<span class="line"><span>       标题栏出现 Accept / Reject</span></span>
<span class="line"><span>  → 你点 Accept：</span></span>
<span class="line"><span>       applyEdit（或 fs.write / delete）写盘</span></span>
<span class="line"><span>       先打开真实文件，再关 diff 预览（减少闪屏）</span></span>
<span class="line"><span>       edit_apply { allow: true } 回 worker</span></span>
<span class="line"><span>  → worker 给模型 ToolResult { ok, applied: true, path }</span></span>
<span class="line"><span>  → 你点 Reject（或关掉 diff 标签）：</span></span>
<span class="line"><span>       关预览，不写盘，模型收到「用户拒绝」</span></span></code></pre></div><p>三种写盘工具<strong>共用</strong>这条线——不是只有 <code>write_file</code> 能预览。<code>str_replace</code> 同样在内存里得到「改前全文 / 改后全文」再 diff；diff 里<strong>只有变了的行</strong>标红绿，没变的行通常对齐显示。</p><hr><h2 id="_3-侧栏-vs-编辑器-谁干什么" tabindex="-1">3. 侧栏 vs 编辑器：谁干什么 <a class="header-anchor" href="#_3-侧栏-vs-编辑器-谁干什么" aria-label="Permalink to &quot;3. 侧栏 vs 编辑器：谁干什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>区域</th><th>本课职责</th></tr></thead><tbody><tr><td><strong>右侧 Webview</strong></td><td>聊天、流式输出、工具名与折叠后的长参数、<code>[diff] str_replace → path</code> 提示</td></tr><tr><td><strong>中间 diff 编辑器</strong></td><td>红绿并排对比、标题栏 <strong>✓ Accept / ✗ Reject</strong></td></tr><tr><td><strong>worker 子进程</strong></td><td>Agent Loop、算提案、等 <code>edit_apply</code>，<strong>不</strong> <code>writeFileSync</code></td></tr></tbody></table><p>这和 <a href="/bagent/chapters/29-agent-split.html">第 29 课</a>、<a href="/bagent/chapters/39-agent-client-protocol.html">第 39 课 ACP</a> 说的分工一致：<strong>Client 画 UI（含 diff），Agent 只出改法</strong>。</p><hr><h2 id="_4-新增事件与-stdio-操作" tabindex="-1">4. 新增事件与 stdio 操作 <a class="header-anchor" href="#_4-新增事件与-stdio-操作" aria-label="Permalink to &quot;4. 新增事件与 stdio 操作&quot;">​</a></h2><h3 id="editproposal-worker-→-插件" tabindex="-1"><code>EditProposal</code>（worker → 插件） <a class="header-anchor" href="#editproposal-worker-→-插件" aria-label="Permalink to &quot;\`EditProposal\`（worker → 插件）&quot;">​</a></h3><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;EditProposal&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;tool&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;str_replace&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;path&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/abs/path/file.c&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;oldContent&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;…改前全文…&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;newContent&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;…改后全文…&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;arguments&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;{…原始 tool 参数…}&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>插件据此打开 diff；<strong>全文走事件管道，不塞进侧栏气泡</strong>（避免几万字符截断）。</p><h3 id="edit-apply-插件-→-worker" tabindex="-1"><code>edit_apply</code>（插件 → worker） <a class="header-anchor" href="#edit-apply-插件-→-worker" aria-label="Permalink to &quot;\`edit_apply\`（插件 → worker）&quot;">​</a></h3><p>用户点 Accept / Reject 后，插件 stdin 一行：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;op&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;edit_apply&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;allow&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>worker 里挂起的 <code>editApply()</code> 返回，Loop 继续给模型回 ToolResult。</p><hr><h2 id="_5-插件侧实现要点" tabindex="-1">5. 插件侧实现要点 <a class="header-anchor" href="#_5-插件侧实现要点" aria-label="Permalink to &quot;5. 插件侧实现要点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文件</th><th>作用</th></tr></thead><tbody><tr><td><code>agent/editProposal.ts</code></td><td>提案类型、<code>parseEditProposal</code>、<code>formatAppliedEdit</code>；写盘工具<strong>不做 output 截断</strong></td></tr><tr><td><code>agent/loop.ts</code></td><td>写盘工具跳过侧栏 <code>approve</code>，走 <code>EditProposal</code> → <code>editApply</code></td></tr><tr><td><code>agent/events.ts</code></td><td><code>EditProposal</code> 事件定义</td></tr><tr><td><code>agent/worker.ts</code></td><td>处理 <code>edit_apply</code></td></tr><tr><td><code>src/diffPreview.ts</code></td><td><code>TextDocumentContentProvider</code>、<code>vscode.diff</code>、关预览、写盘</td></tr><tr><td><code>src/spawn.ts</code></td><td><code>editApply(allow)</code> 转发子进程</td></tr><tr><td><code>src/sidebar.ts</code></td><td>收到 <code>EditProposal</code> 调 diff；长工具参数/结果可折叠</td></tr><tr><td><code>package.json</code></td><td><code>bagent53.acceptEdit</code> / <code>rejectEdit</code> 挂在 <code>diffEditor/title</code></td></tr></tbody></table><p>虚拟 scheme：<code>bagent-old</code>（左）、<code>bagent-new</code>（右）。Accept 成功后：打开磁盘真实文件 → 关 diff 标签 → 侧栏显示「已写盘 …」。</p><hr><h2 id="_6-str-replace-还是-write-file" tabindex="-1">6. <code>str_replace</code> 还是 <code>write_file</code>？ <a class="header-anchor" href="#_6-str-replace-还是-write-file" aria-label="Permalink to &quot;6. \`str_replace\` 还是 \`write_file\`？&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>diff 里常见样子</th><th>建议</th></tr></thead><tbody><tr><td><strong><code>str_replace</code></strong></td><td>只改匹配片段时，diff 上通常一小块红绿</td><td><strong>已有文件优先</strong>；<code>old_string</code> 尽量短</td></tr><tr><td><strong><code>write_file</code></strong></td><td>整文件替换，常大片变动</td><td>新建小文件或确需全文重写时用</td></tr><tr><td><strong><code>delete_file</code></strong></td><td>右栏空文件，表示删除</td><td>删前看清路径</td></tr></tbody></table><p>模型若把整段函数塞进 <code>old_string</code>，diff 仍会显示一大块改动——那是<strong>替换范围大</strong>，不是工具不对。</p><hr><h2 id="_7-动手" tabindex="-1">7. 动手 <a class="header-anchor" href="#_7-动手" aria-label="Permalink to &quot;7. 动手&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ch53:compile</span></span></code></pre></div><ol><li>在 <code>lessons/53-diff-preview</code> <strong>F5</strong> 启动插件（改 <code>package.json</code> 后需重载扩展）</li><li>工作区用<strong>可丢弃的测试目录</strong>（不要拿重要仓库试删改）</li><li>让 Agent <code>str_replace</code> 改一行文案，或 <code>write_file</code> 新建小文件</li><li>应出现并排 diff，标题栏有 <strong>Accept / Reject</strong>（不是侧栏 danger 框）</li><li><strong>Accept</strong> → 磁盘更新、预览关闭、打开真实文件</li><li>再试 <strong>Reject</strong> → 预览关闭，磁盘不变</li></ol><p>终端调试：<code>npm run ch53</code> 无图形 diff，会在提案后文字询问「写盘? [Y/n]」。</p><hr><h2 id="_8-打成-vsix-不用自己-compile" tabindex="-1">8. 打成 .vsix：不用自己 compile <a class="header-anchor" href="#_8-打成-vsix-不用自己-compile" aria-label="Permalink to &quot;8. 打成 .vsix：不用自己 compile&quot;">​</a></h2><p>跟 <a href="/bagent/chapters/33-vscode-vsix.html">第 33 课</a> 一样，可以把本课插件打成 <strong>安装包</strong>，装好后像市场插件一样用，<strong>不必</strong>打开课目录 F5。</p><p>维护者在仓库根目录：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ch53:package</span></span></code></pre></div><p>会 <code>npm install</code> → <code>compile</code> → <code>vsce package</code>，产出：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lessons/53-diff-preview/bagent-0.0.1.vsix</span></span></code></pre></div><p>把这个 <code>.vsix</code> 发给学习者即可。面向用户的固定下载入口：<a href="https://github.com/SyncLionPaw/bagent/releases/latest" target="_blank" rel="noreferrer">GitHub Releases · bagent-plugin.vsix</a>（见 <a href="/bagent/guide/install-plugin.html">安装插件</a>）。</p><p><strong>安装（VS Code / Cursor）</strong></p><ol><li>扩展面板右上角 <code>⋯</code> → <strong>从 VSIX 安装…</strong> → 选上面的文件</li><li>或终端：</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cursor</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --install-extension</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/bagent-0.0.1.vsix</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># code --install-extension …   # 纯 VS Code</span></span></code></pre></div><ol start="3"><li>配置 <code>~/.bagent/deepseek-api-key</code>（或 <code>export DEEPSEEK_API_KEY</code>）</li><li>命令面板运行 <strong>bagent: 打开 Agent 面板</strong>，或点右侧辅助栏 bagent 图标</li></ol><p>发布给用户时扩展名显示为 <strong>bagent</strong>（带 logo 与 README）。内部命令 ID 仍为 <code>bagent53</code>，与第 51、52 课插件可并存，但一般只启用一个。</p><hr><h2 id="检查点" tabindex="-1">检查点 <a class="header-anchor" href="#检查点" aria-label="Permalink to &quot;检查点&quot;">​</a></h2><ul><li>[ ] 写盘工具不再走侧栏 ✓/✗？</li><li>[ ] diff 在<strong>编辑器中间</strong>打开，标题栏能 Accept / Reject？</li><li>[ ] Accept 后内容正确，且预览 tab 已关闭？</li><li>[ ] Reject 或关 diff 标签后磁盘未变？</li><li>[ ] 读过 <a href="/bagent/chapters/52-edit-proposal.html">第 52 课</a> 提案在 worker 里怎么算？</li></ul><hr><p><a href="/bagent/chapters/52-edit-proposal.html">← 第 52 课</a></p>`,56)])])}const k=e(n,[["render",o]]);export{g as __pageData,k as default};
